INSERT INTO `faqs` (`id`, `question`, `answer`, `display_order`, `created_at`, `updated_at`) VALUES
(1, 'Which locations are included in your service area?', 'Morong Bataan\r\nSBMA (Subic Bay Freeport Zone)\r\nOlongapo City\r\nSubic\r\nCastillejos, Zambales\r\nSan Marcelino, Zambales\r\nSan Antonio, Zambales\r\nSan Narciso, Zambales\r\nSan Felipe, Zambales\r\nCabangan, Zambales\r\nBotolan, Zambales\r\nIba, Zambales', 1, '2025-03-30 02:46:29', '2025-04-05 14:22:24'),
(2, 'May we see a copy of your contract?', 'Yes. Once your order has been approved we will provide a copy of your contract through your email.', 2, '2025-03-30 02:46:29', '2025-04-05 14:22:24'),
(3, 'What payments do you accept?', 'We accept E-Wallet (Gcash), Bank Transfer, and Cash', 3, '2025-03-30 02:46:29', '2025-03-30 02:46:29'),
(4, 'Do you require a deposit?', 'Yes, your items are not reserved until a 50% deposit is received.\nThe remaining 50% is due on the day of delivery.', 4, '2025-03-30 02:46:29', '2025-03-30 02:46:29'),
(5, 'Do your rental rates vary based on the duration of the rental period?', 'Our base rates apply to single-day rentals (up to 24 hours). For extended rental periods, we apply a graduated pricing structure where rates increase incrementally with each additional day. This accounts for the extended use and reduced availability of our inventory. We\'re happy to provide a detailed quote for your specific rental duration and items.', 5, '2025-03-30 02:46:29', '2025-03-30 02:46:29'),
(6, 'What are your delivery charges and how are they calculated?', 'Our delivery fees are calculated based on order size, distance, and specific delivery requirements. A customized quote will be provided during your order confirmation process once we review your location and rental items. This allows us to ensure accurate pricing based on your unique event needs.', 6, '2025-03-30 02:46:29', '2025-03-30 02:46:29'),
(7, 'Do you offer set up services?', 'Yes, we offer setup services for all rentals. The setup fee is calculated as a percentage of your order\'s total value. This service includes professional installation, proper equipment arrangement, and basic troubleshooting to guarantee your event runs smoothly.', 7, '2025-03-30 02:46:29', '2025-03-30 02:46:29'),
(8, 'What is your policy for damaged or lost rental items?', 'Customers are responsible for damaged or missing items. We charge replacement costs at current market value.', 8, '2025-03-30 02:46:29', '2025-03-30 02:46:29'),
(9, 'Can I pick up the rental items myself?', 'Yes! We offer a customer pickup option for your convenience. You can pick up your chairs and tables directly from our location during our designated pickup hours.', 9, '2025-03-30 02:46:29', '2025-03-30 02:46:29'),
(10, 'Where and when can I pick up my items?', 'Pickups are available at Linusungan, San Marcelino, Zambales. Our pickup hours are Monday – Sunday 8:00 AM - 6:00 PM. Please confirm your pickup time when placing your order to ensure availability.', 10, '2025-03-30 02:46:29', '2025-03-30 02:46:29'),
(11, 'Do I need to bring anything for pickup?', 'Please bring a valid ID and your order confirmation (either printed or on your phone). You\'ll also need a vehicle suitable for transporting the items—check the dimensions and quantities in your order to ensure they\'ll fit!', 11, '2025-03-30 02:46:29', '2025-03-30 02:46:29'),
(12, 'Can I return the items myself?', 'Yes, you can drop off the items at the same location during our return hours. Please ensure items are clean and in good condition to avoid additional fees.', 12, '2025-03-30 02:46:29', '2025-03-30 02:46:29'),
(13, 'What if I need to cancel or change my pickup order?', 'You can notify us to modify or cancel your reservation.', 13, '2025-03-30 02:46:29', '2025-03-30 02:46:29'),
(14, 'Are there any extra fees for picking up myself?', 'No! Choosing pickup saves you delivery fees. You only pay for the rental items and any applicable taxes or deposits.', 14, '2025-03-30 02:46:29', '2025-03-30 05:42:56');
INSERT INTO `homepage_content` (`id`, `section`, `content_type`, `content`, `updated_at`) VALUES
(1, 'hero_title', 'text', 'Welcome to Jun Mar Chairs and Tables', '2025-03-30 05:03:58'),
(2, 'hero_text', 'text', 'We specialize in providing top-quality Table and Chair rentals to make your events effortless and comfortable. Discover the perfect setup for your occasion today!', '2025-03-30 05:03:58'),
(3, 'hero_image', 'image', '/Admin_Page/adminpages/uploads/67e8d0be909ad.jpg', '2025-03-30 05:03:58'),
(4, 'about_title', 'text', 'About Us', '2025-03-30 06:01:18'),
(5, 'about_text', 'text', '<p>At Jun Mar Chair\'s and Table\'s Rental, our mission is to work closely with our customers, collaborating with them to craft the perfect event experience. We understand that every event is distinct, and we\'re here to help you bring your vision to life. Whether you have a clear idea of what you need or require assistance in selecting the right items, our dedicated team is ready to assist you every step of the way.</p>\r\n\r\n<p>Our commitment to delivering exceptional value is reflected in our approach. We take pride in offering superior quality products, combined with competitive pricing, to ensure that you get the best value for your investment. Your satisfaction is our priority, and we strive to exceed your expectations with both our service and our rental\r\nofferings.</p>\r\n\r\n<p>As a dynamic and forward-thinking business, Jun Mar Chair\'s and Table\'s Rental is continuously growing and evolving. If you don\'t find precisely what you\'re looking for on our website, we encourage you to get in touch with us.</p>', '2025-03-30 06:07:25'),
