(30, 'warehouse_hours', 'text', '<table>\r\n                                <tr><td>Sunday</td><td>7:00 AM - 5:00 PM</td></tr>\r\n                                <tr><td>Monday</td><td>7:00 AM - 5:00 PM</td></tr>\r\n                                <tr><td>Tuesday</td><td>7:00 AM - 5:00 PM</td></tr>\r\n                                <tr><td>Wednesday</td><td>7:00 AM - 5:00 PM</td></tr>\r\n                                <tr><td>Thursday</td><td>7:00 AM - 5:00 PM</td></tr>\r\n                                <tr><td>Friday</td><td>7:00 AM - 5:00 PM</td></tr>\r\n                                <tr><td>Saturday</td><td>7:00 AM - 5:00 PM</td></tr>\r\n                            </table>', '2025-03-30 06:13:13'),
